using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using OfficeOpenXml;
namespace SchoolWorkdayCalculator {
internal sealed partial class MainForm {
 internal Action<string,string,MessageBoxIcon> TestMessage;
 void Notify(string text,string title,MessageBoxIcon icon){if(TestMessage!=null)TestMessage(text,title,icon);else MessageBox.Show(text,title,MessageBoxButtons.OK,icon);}
 static string Inputs(MainForm f){return f.year.Value+"|"+f.summerStart.Value.Date+"|"+f.summerEnd.Value.Date+"|"+f.winterStart.Value.Date+"|"+f.winterEnd.Value.Date+"|"+String.Join(";",f.discretionary.Select((p,i)=>p.Checked+":"+p.Value.Date+":"+f.discretionaryNotes[i].Text))+"|"+String.Join(";",f.extras.Select(x=>x.Date+":"+x.Name))+"|"+f.outputFolder.Text;}
 internal static string Helper(DateTime d){int[] rows={5,14,22,31,39,48};int index=(d.Month+9)%12,position=(int)new DateTime(d.Year,d.Month,1).DayOfWeek+d.Day-1;return ExcelCellBase.GetAddress(rows[index%6]+position/7,(index<6?27:34)+position%7);}
 internal static void TestNonConsent(string folder){Directory.CreateDirectory(folder);int count=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception(name);count++;};try{
  var s=new Settings{Year=2026,NonConsent=true,Summer=new DateRange(new DateTime(2026,7,21),new DateTime(2026,8,2),"여름방학"),Winter=new DateRange(new DateTime(2026,12,21),new DateTime(2027,2,28),"겨울방학"),Discretionary=new List<DateTime>(),DiscretionaryNames=new Dictionary<DateTime,string>(),Extras=new List<ExtraHoliday>(),OutputFolder=folder};
  var holidays=HolidayCalculator.GetFiscalHolidays(s.Year);Func<int,int,int,DateTime> d=(y,m,day)=>new DateTime(y,m,day);
  check(NonConsentPolicy.Code(s,d(2026,12,25),holidays)=="N","Christmas in vacation unpaid");check(NonConsentPolicy.Code(s,d(2027,1,1),holidays)=="N","New Year in vacation unpaid");check(NonConsentPolicy.Code(s,d(2027,1,2),holidays)=="N"&&NonConsentPolicy.Code(s,d(2027,1,3),holidays)=="N","holiday alone does not create paid weekend");
  check(NonConsentPolicy.Code(s,d(2026,7,21),holidays)=="N","first vacation day not automatic work");check(NonConsentPolicy.Code(s,d(2026,7,31),holidays)=="N","last five days not automatic work");check(NonConsentPolicy.Code(s,d(2026,7,25),holidays)=="S"&&NonConsentPolicy.Code(s,d(2026,7,26),holidays)=="U","vacation start week with term work gets paid weekend");
  check(NonConsentPolicy.Code(s,d(2026,8,1),holidays)=="N"&&NonConsentPolicy.Code(s,d(2026,8,2),holidays)=="N","full no-work vacation week weekend unpaid");check(NonConsentPolicy.Code(s,d(2026,10,9),holidays)=="H","term public holiday remains paid");
  var result=WorkbookBuilder.Build(Path.Combine(folder,"비동의자_기본예시.xlsx"),s);
  using(var book=new ExcelPackage(new FileInfo(Path.Combine(folder,"비동의자_기본예시.xlsx")))){check(book.Workbook.Worksheets.Count==3,"two calendars and copy sheet exported");var sheet=book.Workbook.Worksheets[2];check(sheet.Name=="320일 비동의자"&&sheet.Cells[1,1].Text.Contains("비동의자"),"nonconsent sheet correctly labelled");check(sheet.Cells[Helper(d(2027,1,1))].Text=="N","unpaid holiday persisted in XLSM");check(sheet.Cells[Helper(d(2026,7,25))].Text=="S","paid vacation start Saturday persisted");check(sheet.Cells[Helper(d(2026,7,21))].Text=="N","no 320 cleaning days in XLSM");check(sheet.Cells[56,6].GetValue<int>()==4,"learning leave remains paid and reduces prescribed work only");check(book.Workbook.Worksheets.Select(x=>x.Name).SequenceEqual(new[]{"상시근로자","320일 비동의자",WorkbookBuilder.PrescribedWorkdaySheet}),"calendar tabs and copy sheet in order");check(book.Workbook.VbaProject==null,"workbook contains no macros");}
  s.Summer=new DateRange(d(2026,4,27),d(2026,5,10),"봄방학");check(NonConsentPolicy.Code(s,d(2026,5,1),holidays)=="H","labour day retained as separate paid holiday during vacation");check(NonConsentPolicy.Code(s,d(2026,5,5),holidays)=="N","Children's Day in vacation unpaid");check(NonConsentPolicy.Code(s,d(2026,5,2),holidays)=="N","labour day alone does not generate paid weekend");s.Discretionary.Add(d(2026,5,4));holidays[d(2026,5,4)]="재량휴업일";check(NonConsentPolicy.Code(s,d(2026,5,4),holidays)=="H","discretionary holiday separately paid");check(NonConsentPolicy.DiscretionaryCount(s)==1,"valid discretionary day reduces learning leave");s.Discretionary.Add(d(2026,5,1));s.Discretionary.Add(d(2026,5,2));check(NonConsentPolicy.DiscretionaryCount(s)==1,"public holiday and weekend cannot reduce learning leave");s.Discretionary.Clear();WorkbookBuilder.Build(Path.Combine(folder,"비동의자_노동절예시.xlsx"),s);
  using(var f=new MainForm{Offscreen=true,ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(SystemInformation.VirtualScreen.Right+200,SystemInformation.VirtualScreen.Top)}){f.Show();Application.DoEvents();f.year.Value=2026;f.outputFolder.Text=folder;f.summerEnd.Value=d(2026,8,12);f.discretionary[0].Value=d(2026,5,4);f.discretionary[0].Checked=true;f.discretionaryNotes[0].Text="학교장 재량휴업";f.extras.Add(new ExtraHoliday{Date=d(2026,10,16),Name="학교 휴일"});f.RefreshExtras();string before=Inputs(f);f.nonConsentMenu.PerformClick();Application.DoEvents();check(f.BuildSettings().NonConsent,"navigation sets actual export mode");check(Inputs(f)==before,"all input values retained on nonconsent switch");check(f.modeSubheading.Text.Contains("비동의자")&&f.createButton.Text=="엑셀 생성","heading and generate button indicate selected mode");check(!Descendants(f).OfType<Label>().Any(x=>x.Text.StartsWith("01 ")||x.Text.StartsWith("02 ")||x.Text.StartsWith("03 ")),"old three step hints removed");f.Snapshot(Path.Combine(folder,"비동의자_화면.png"));string message="";f.TestMessage=(text,title,icon)=>{message=title+":"+text;if(title=="오류")throw new Exception(text);};f.createButton.PerformClick();check(File.Exists(Path.Combine(folder,"2026학년도_320일비동의자_근로일수_산정.xlsx")),"actual UI button creates separate nonconsent file");check(message.Contains("비동의자 소정근로일수")&&!message.Contains("320일 기준보다"),"nonconsent completion has no 320-day shortage claim");f.consentMenu.PerformClick();check(Inputs(f)==before&&!f.BuildSettings().NonConsent,"return to 320 retains inputs and original mode");f.createButton.PerformClick();check(File.Exists(Path.Combine(folder,"2026학년도_교육공무직_근로일수_산정.xlsx")),"original mode uses separate original filename");f.nonConsentMenu.PerformClick();check(Inputs(f)==before,"repeated menu switching retains all data");f.Hide();}
  File.WriteAllText(Path.Combine(folder,"nonconsent-tests.txt"),"PASS "+count+" policy, public-holiday/labour-day, weekend, prescribed/paid-day, XLSM basis, navigation and actual generate-button checks\nDefault nonconsent sample: prescribed "+result.SeasonalWorkDays+", paid "+result.SeasonalPaidDays);
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"nonconsent-tests.txt"),ex.ToString());Environment.ExitCode=1;}}
}
}
